### JsonInputFilter code used in this test

``` php
<?php
namespace App\Routing\Filter;

use Cake\Event\Event;
use Cake\Log\Log;
use Cake\Network\Exception\BadRequestException;
use Cake\Routing\DispatcherFilter;

class JsonInputFilter extends DispatcherFilter
{

    /**
     * Before dispatch callback.
     *
     * @param \Cake\Event\Event $event The beforeDispatch event.
     * @return void
     */
    public function beforeDispatch(Event $e)
    {
        Log::write(LOG_DEBUG, '-------------------------------------------------');
        Log::write(LOG_DEBUG, print_r(getallheaders(), true));
        Log::write(LOG_DEBUG, 'Authorization: ' . $e->data['request']->header('Authorization'));
        Log::write(LOG_DEBUG, 'Host: ' . $e->data['request']->header('Host'));
        Log::write(LOG_DEBUG, 'Connection: ' . $e->data['request']->header('Connection'));
        Log::write(LOG_DEBUG, 'Content-Length: ' . $e->data['request']->header('Content-Length'));
        Log::write(LOG_DEBUG, 'Origin: ' . $e->data['request']->header('Origin'));
        Log::write(LOG_DEBUG, 'User-Agent: ' . $e->data['request']->header('User-Agent'));
        Log::write(LOG_DEBUG, 'Content-Type: ' . $e->data['request']->header('Content-Type'));
        Log::write(LOG_DEBUG, 'Accept: ' . $e->data['request']->header('Accept'));
        Log::write(LOG_DEBUG, 'Referer: ' . $e->data['request']->header('Referer'));
        Log::write(LOG_DEBUG, 'Accept-Encoding: ' . $e->data['request']->header('Accept-Encoding'));
        Log::write(LOG_DEBUG, 'Accept-Language: ' . $e->data['request']->header('Accept-Language'));
        Log::write(LOG_DEBUG, 'Cookie: ' . $e->data['request']->header('Cookie'));
        Log::write(LOG_DEBUG, '-------------------------------------------------');

        // Get HTTP headers, case insensitive:
        $headers = getallheaders();
        debug($headers);
        foreach ($headers as $key => $value) {
            unset($headers[$key]);
            $headers[strtolower($key)] = $value;
        }
        // Check for JSON content-type:
        if (isset($headers['content-type']) === false) {
            return;
        }
        if (strpos($headers['content-type'], 'application/json') === false) {
            return;
        }
        // JSON header has been set, JSON body is expected to exist:
        if (empty($e->data['request']->input())) {
            throw new BadRequestException('JSON HTTP-body missing.');
        }
        $jsonHttpBody = json_decode($e->data['request']->input(), true);
        if (json_last_error() !== JSON_ERROR_NONE) {
            throw new BadRequestException('Invalid JSON HTTP-body given: ' . json_last_error_msg() . '.');
        }
        $e->data['request']->data = $jsonHttpBody;
    }
}
```

